const q=s=>document.querySelector(s);let renderer,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,raining=true,raf=0,busy=false;
function frame(t){raf=0;if(!renderer||document.hidden||!playing)return;renderer.render(t);raf=requestAnimationFrame(frame)}
function updateFrame(){if(renderer){renderer.render(performance.now());if(playing&&!document.hidden&&!raf)raf=requestAnimationFrame(frame)}}
q('#enter').addEventListener('click',async()=>{if(busy||renderer)return;busy=true;q('#enter').disabled=true;q('#status').textContent='Собираем ночной сад…';try{const {createTempleNightRenderer}=await import('./temple-renderer.js');await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));renderer=createTempleNightRenderer(q('#world'));q('.sanctuary').classList.add('ready');q('#status').textContent='Выберите точку обзора внизу.';document.querySelectorAll('.controls button,.controls input').forEach(e=>e.disabled=false);q('#pause').textContent=playing?'Ⅱ Пауза':'▷ Движение';q('#pause').setAttribute('aria-pressed',!playing);updateFrame()}catch(error){q('#status').textContent='3D недоступно в этом браузере. Графический пролог остаётся доступным.';q('#enter').textContent='Попробовать ещё раз';q('#enter').disabled=false;console.error(error)}finally{busy=false}});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{renderer?.setView(Number(b.dataset.view));document.querySelectorAll('[data-view]').forEach(a=>a.setAttribute('aria-pressed',a===b));updateFrame()}));
q('#rain').addEventListener('click',()=>{raining=!raining;renderer?.setRain(raining);q('#rain').setAttribute('aria-pressed',raining);updateFrame()});q('#light').addEventListener('input',e=>{renderer?.setLight(Number(e.target.value)/100);q('#light-value').textContent=e.target.value+'%';updateFrame()});
q('#pause').addEventListener('click',()=>{playing=!playing;q('#pause').setAttribute('aria-pressed',!playing);q('#pause').textContent=playing?'Ⅱ Пауза':'▷ Движение';if(!playing){cancelAnimationFrame(raf);raf=0}else updateFrame()});
q('.sanctuary').addEventListener('pointermove',e=>{const r=q('.sanctuary').getBoundingClientRect();renderer?.setPointer((e.clientX-r.left)/r.width*2-1,-((e.clientY-r.top)/r.height*2-1));if(!playing)updateFrame()});q('.sanctuary').addEventListener('pointerleave',()=>renderer?.setPointer(0,0,false));window.addEventListener('resize',()=>{renderer?.resize();updateFrame()});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0}else updateFrame()});window.addEventListener('pagehide',event=>{cancelAnimationFrame(raf);raf=0;if(!event.persisted){renderer?.dispose();renderer=null}});window.addEventListener('pageshow',event=>{if(event.persisted)updateFrame()});
